// src/core/case_fold.hpp (internal to navigator_core)
//
// Purpose: locale-independent simple case folding of one code point, as specified in
//          navigator/fs.hpp ("Case folding"): Unicode CaseFolding.txt statuses C + S, plus the
//          Navigator Turkish extension U+0130 -> U+0069 and U+0131 -> U+0069.
// Data:    case_fold_data.inc, generated by tools/gen_case_fold.py from CaseFolding-15.1.0.txt
//          (Unicode 15.1.0, all 1457 C+S mappings, full code space; nothing hand-written).
// Thread-safety: pure function over constant data.
#pragma once

#include <string_view>

namespace navigator::core {

// Unicode version of the embedded CaseFolding.txt.
[[nodiscard]] std::string_view case_folding_unicode_version() noexcept;

// Out-of-line part of fold_code_point() for cp >= 0x80.
[[nodiscard]] char32_t fold_non_ascii(char32_t cp) noexcept;

// Simple case fold of one code point. Values that are not Unicode scalar values (escaped bytes
// U+DC80..U+DCFF) are returned unchanged. The fold is idempotent.
[[nodiscard]] inline char32_t fold_code_point(char32_t cp) noexcept {
    if (cp < 0x80) {
        return (cp >= U'A' && cp <= U'Z') ? cp + 0x20 : cp;
    }
    return fold_non_ascii(cp);
}

} // namespace navigator::core
